#!/usr/bin/env texlua

---@diagnostic disable: lowercase-global
module = "dichromacy"

sourcefiledir = "src"
sourcefiles = { "*.dtx", "*.ins", "*.lua" }
unpackfiles = { "*.ins" }
installfiles = { "*.sty", "*.lua" }
-- The .lua file needs to be treated as both source and installable
-- Since it's not generated by docstrip, add it to unpacksuppfiles
unpacksuppfiles = { "*.lua" }

docfiledir = "docs"
typesetfiles = { "*.tex" }
docfiles = { "dichromacy.pdf" }
textfiles = { "*.md", "LICENSE" }
checkengines = { "luatex" }
checksuppfiles = { "*.tex" }

packtdszip = false

uploadconfig = {
	pkg = "dichromacy",
	version = "0.3.0",
	author = "Johan Larsson, Simon Pfahler",
	uploader = "Johan Larsson",
	email = "johanlarsson@outlook.com",
	update = false,
	license = "mit",
	summary = "Color vision deficiency simulation for LaTeX documents",
	description = "Simulate color vision deficiencies in LaTeX documents, including "
		.. "protanopia, deuteranopia, and tritanopia. This package provides "
		.. "a few simple commands that allow you to control both the type "
		.. "of color deficiency and the severity of the simulation.",
	ctanPath = "/macros/latex/contrib/dichromacy",
	repository = "https://github.com/jolars/dichromacy",
	bugtracker = "https://github.com/jolars/dichromacy/issues",
	topic = { "colour", "accessible", "luatex" },
	announcement_file = "ctan_announcement.txt",
}
